```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT (COUNT(DISTINCT ?k) AS ?issuersRated) (COUNT(DISTINCT ?kgb) AS ?gb) WHERE {
  { SELECT ?k ?basis (MAX(?d) AS ?md) WHERE {
      ?a lad:ratedThing ?e ; lad:date ?d ; lad:ratingType lad:type-LTIDR .
      OPTIONAL{?a lad:ccyBasis ?basis}
      ?e lad:sourceSystem ?s . FILTER(?s != "QA")
      OPTIONAL{?e lad:lei ?lei} BIND(COALESCE(?lei,STR(?e)) AS ?k)
      FILTER(?d <= "2026-10-01"^^xsd:date)
    } GROUP BY ?k ?basis }
  ?a2 lad:ratedThing ?e2 ; lad:date ?md ; lad:ratingType lad:type-LTIDR ; lad:rating ?r .
  OPTIONAL{?a2 lad:ccyBasis ?b2}
  FILTER(!bound(?basis) || ?basis = ?b2)
  ?e2 lad:sourceSystem ?s2 . FILTER(?s2 != "QA")
  OPTIONAL{?e2 lad:lei ?l2} FILTER(COALESCE(?l2,STR(?e2)) = ?k)
  FILTER(?r != "WD")
  ?e2 lad:country ?c .
  FILTER NOT EXISTS { ?e3 lad:lei ?k ; lad:sourceSystem "RESEARCH" ; lad:country ?c3 . FILTER(?c3 != "GB") }
  BIND(IF(?c="GB", ?k, ?unb) AS ?kgb)
}
```

